from time import perf_counter
from cadence import agenda, occurrences, PlanError
huge = 10**5000
rule = {'id':'safe','rule':'every day at 08:00 for 1m from 2025-01-01'}
p = {'timezone': 'UTC', 'rules': [rule]}
ov = {'rule': 'safe', 'key': '2025-01-01', 'action': 'move', 'to': '2025-01-01T08:00'}
lo, hi = '2025-01-01T00:00Z', '2025-01-02T00:00Z'
for bad_plan,start in [
    (dict(p, timezone=huge), lo), (dict(p, rules=[dict(rule,id=huge)]), lo),
    (dict(p, overrides=[dict(ov,key=huge)]), lo), (dict(p,overrides=[dict(ov,action=[huge])]), lo),
    (dict(p, overrides=[dict(ov, rule=huge)]), lo), (dict(p,overrides=[dict(ov, **{'for':huge})]),lo),
    (dict(p,min_segment=huge), lo), (p, huge),
]:
    for fn in (agenda, occurrences):
        try:
            fn(bad_plan, start, hi)
        except PlanError:
            continue
        raise AssertionError('invalid value was accepted')
assert occurrences(dict(p,rules=[dict(rule,priority=huge)]), lo, hi)
for text, start, end, count in [
    ('every day at 08:00 for 1m from 1970-01-01', '2060-02-01T00:00Z','2060-02-02T00:00Z', 200),
    ('every 12 months on 30 at 08:00 for 1m from 0001-02-01 times 1', '9998-02-01T00:00Z','9998-02-02T00:00Z', 0),
]:
    raw = {'timezone': 'UTC','rules': [{'id': str(i), 'rule':text} for i in range(200)]}
    t = perf_counter()
    assert len(occurrences(raw,start,end)) == count
    print(f'200 rules anchored {text.split(\" from \")[1][:10]}: {(perf_counter()-t)*1000:.1f} ms')
PY"

